func TestLibraryScanners_Find(t *testing.T) {
	type args struct {
		name string
	}
	tests := []struct {
		name string
		lss  LibraryScanners
		args args
		want map[string]types.Library
	}{
		{
			name: "single file",
			lss: LibraryScanners{
				{
					Path: "/pathA",
					Libs: []types.Library{
						{
							Name:    "libA",
							Version: "1.0.0",
						},
					},
				},
			},
			args: args{"libA"},
			want: map[string]types.Library{
				"/pathA": {
					Name:    "libA",
					Version: "1.0.0",
				},
			},
		},
		{
			name: "multi file",
			lss: LibraryScanners{
				{
					Path: "/pathA",
					Libs: []types.Library{
						{
							Name:    "libA",
							Version: "1.0.0",
						},
					},
				},
				{
					Path: "/pathB",
					Libs: []types.Library{
						{
							Name:    "libA",
							Version: "1.0.5",
						},
					},
				},
			},
